function(container, apiUrl, tables) {
  let selectedUrgency = '';
  let selectedPhotos = [];

  // 現在日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#incident-datetime').value = now.toISOString().slice(0, 16);

  // 作業項目マスタを読み込み（テーブルインデックス3）
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3);
    const select = container.querySelector('#work-item');
    if (workItems) {
      workItems.forEach(item => {
        const option = document.createElement('option');
        option.value = item.id;
        option.textContent = `${item.作業項目コード || ''} - ${item.作業項目名 || ''}`;
        select.appendChild(option);
      });
    }
  }

  // 報告者名を設定（ログインユーザー情報から）
  async function loadReporter() {
    const users = await window.aivicApi.list(0);
    if (users && users.length > 0) {
      // 最初のユーザーを現在のログインユーザーとして扱う
      container.querySelector('#reporter-name').value = users[0].氏名 || '';
    }
  }

  // 緊急度ボタンのイベント
  container.querySelectorAll('.urgency-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      // 全ボタンをリセット
      container.querySelectorAll('.urgency-btn').forEach(b => {
        b.style.background = 'transparent';
      });
      // 選択されたボタンを強調
      btn.style.background = btn.style.borderColor;
      btn.style.color = '#fff';
      selectedUrgency = btn.dataset.level;
    });
  });

  // 写真選択
  container.querySelector('#photo-btn').addEventListener('click', () => {
    container.querySelector('#photo-input').click();
  });

  container.querySelector('#photo-input').addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    selectedPhotos = files;

    // 枚数表示
    container.querySelector('#photo-count').textContent = `${files.length}枚選択`;

    // プレビュー表示
    const preview = container.querySelector('#photo-preview');
    preview.innerHTML = '';

    files.forEach((file, index) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = document.createElement('img');
        img.src = e.target.result;
        img.style.cssText = 'width: 80px; height: 80px; object-fit: cover; border-radius: 4px; border: 1px solid rgba(255,255,255,0.18);';
        preview.appendChild(img);
      };
      reader.readAsDataURL(file);
    });
  });

  // 下書き保存
  container.querySelector('#btn-draft').addEventListener('click', async () => {
    const reportData = {
      緊急度: selectedUrgency,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#incident-datetime').value,
      発生場所: container.querySelector('#incident-location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#incident-content').value,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      写真枚数: selectedPhotos.length,
      状態: '下書き',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    // 緊急報告用の新しいテーブルとして保存（仮想テーブルインデックス99）
    const saved = await window.aivicApi.save(99, reportData);
    if (saved) {
      alert('下書きを保存しました');
    }
  });

  // 即座に報告
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    // 必須項目チェック
    if (!selectedUrgency) {
      alert('緊急度を選択してください');
      return;
    }
    if (!container.querySelector('#report-type').value) {
      alert('報告種別を選択してください');
      return;
    }
    if (!container.querySelector('#incident-content').value.trim()) {
      alert('緊急事態内容を入力してください');
      return;
    }

    const reportData = {
      緊急度: selectedUrgency,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#incident-datetime').value,
      発生場所: container.querySelector('#incident-location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#incident-content').value,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      写真枚数: selectedPhotos.length,
      状態: '報告済み',
      報告日時: new Date().toISOString(),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(99, reportData);
    if (saved) {
      alert('緊急報告を送信しました');
      // フォームをリセット
      container.querySelector('#report-type').value = '';
      container.querySelector('#incident-location').value = '';
      container.querySelector('#work-item').value = '';
      container.querySelector('#incident-content').value = '';
      container.querySelector('#contact-phone').value = '';
      container.querySelector('#photo-preview').innerHTML = '';
      container.querySelector('#photo-count').textContent = '0枚選択';
      selectedPhotos = [];
      selectedUrgency = '';
      container.querySelectorAll('.urgency-btn').forEach(b => {
        b.style.background = 'transparent';
        b.style.color = b.style.borderColor;
      });
    }
  });

  // 報告完了ボタン
  container.querySelector('#btn-complete').addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // 初期データ読み込み
  loadWorkItems();
  loadReporter();
}
